        {"영어원문":"It tries the faith and patience of God's people when wickedness goes unpunished.", "한국어번역":"악이 처벌받지 않을 때 하나님의 백성의 믿음과 인내가 시험받는다.", "핵심통찰":"악의 형통은 신앙의 시험대이며 인내를 통해 성숙해진다"}
