    표6_설교자료: [
        {"대지":"제목", "내용":"놀라고 또 놀라라 — 예상을 초월하시는 하나님", "예화_적용":"하나님의 방법은 항상 우리의 상상을 넘어선다"},
        {"대지":"서론", "내용":"하박국의 질문에 대한 하나님의 첫 번째 응답이 시작된다. 놀랍게도 하나님은 이방 나라 바벨론을 사용하겠다고 선언하시니 인간의 예상을 완전히 뒤엎는 대답이다", "예화_적용":"의사에게 치료법을 물었더니 예상과 전혀 다른 처방을 받은 것과 같다"},
        {"대지":"1대지: 열국을 보라 (하비투)", "내용":"하나님은 우리의 좁은 시야를 넓혀 세계적 관점에서 보라고 하신다. 하나님의 역사는 한 나라에 국한되지 않는다", "예화_적용":"GPS로 확대하면 좁은 골목이 큰 도시의 일부인 것처럼 하나님의 계획은 우리가 보는 것보다 크다"},
        {"대지":"2대지: 놀라고 또 놀라라 (테마후)", "내용":"하나님의 역사는 두 번 놀랄 만큼 충격적이다. 첫째 바벨론이 심판 도구라는 사실, 둘째 그것이 하나님의 계획이라는 사실이다", "예화_적용":"불 속에서 세 사람과 함께하시는 하나님처럼 위기 속에 하나님의 계획이 있다"},
        {"대지":"3대지: 믿지 못할 역사 (로 타아미누)", "내용":"하나님의 계획은 때로 인간의 이해를 초월하여 들어도 믿기 어렵지만 반드시 이루어진다", "예화_적용":"과학 법칙이 직관에 반하듯 하나님의 방법도 우리 논리를 초월하지만 확실하다"},
        {"대지":"결론", "내용":"하나님의 방법이 이해되지 않을 때 놀라되 신뢰하자. 하나님은 우리 생전에 놀라운 일을 행하고 계신다", "예화_적용":"이해 못해도 신뢰하는 것이 진정한 믿음이며 하나님은 그 믿음에 응답하신다"}
    ],
