        {"항목":"사나운 정복자", "내용":"바벨론은 잔인하고 신속한 군사 행동으로 유명했으며 주변국을 차례로 정복하였다", "목회적활용":"하나님이 허용하시는 시련은 목적이 있으며 그 안에서도 하나님의 보호가 있다"},
        {"항목":"하나님의 도구로서의 바벨론", "내용":"하나님이 직접 바벨론을 일으켰다고 선언하시며 이방 나라도 하나님의 계획의 도구임을 밝히신다", "목회적활용":"하나님은 모든 수단을 사용하시며 그 어떤 것도 하나님의 통제 밖에 있지 않다"}
