        {"대지":"서론", "내용":"하나님은 하박국의 질문에 충격적인 답을 주신다. 유다의 죄를 심판하기 위해 더 악한 바벨론을 사용하시겠다는 것이다", "예화_적용":"감염된 상처를 치료하기 위해 고통스러운 수술이 필요하듯 하나님의 심판에는 치유의 목적이 있다"},
        {"대지":"1대지: 하나님이 일으키심 (메킴)", "내용":"바벨론의 부상은 우연이 아니라 하나님의 주권적 행위이다. 역사의 모든 변화 뒤에 하나님이 계신다", "예화_적용":"체스 경기에서 모든 수를 내다보는 것처럼 하나님은 역사의 모든 흐름을 주관하신다"},
        {"대지":"2대지: 사납고 성급한 백성 (함마르, 한님하르)", "내용":"바벨론의 잔인함과 속도는 두려움의 대상이지만 이조차 하나님의 통제 안에 있다", "예화_적용":"사나운 불도 소방관의 통제 안에서 맞불놓기에 사용되듯 하나님은 악도 통제하신다"},
        {"대지":"3대지: 남의 것을 점령하는 탐욕", "내용":"자기 소유가 아닌 것을 점령하는 것은 결국 심판의 대상이 된다. 도구가 스스로 주인이 되려 할 때 심판받는다", "예화_적용":"도끼가 자기를 찍는 자를 자랑할 수 없듯 도구가 주인 행세를 하면 심판받는다"},
        {"대지":"결론", "내용":"하나님의 방법이 이해되지 않을 때도 하나님의 주권을 신뢰하자. 심판의 도구도 결국 심판받으시니 하나님의 정의는 완전하다", "예화_적용":"의사의 처방이 이해되지 않아도 신뢰하듯 하나님의 방법을 믿고 따르자"}
