        {"항목":"교만한 바벨론과 의로운 잔존자", "내용":"교만한 바벨론과 대비되는 믿음의 의인이라는 두 가지 삶의 방식을 제시한다", "목회적활용":"교만과 믿음 두 길 중 어느 길을 선택할 것인가가 인생의 가장 중요한 결단이다"},
        {"항목":"신약에서의 인용", "내용":"이 구절은 로마서 1:17 갈라디아서 3:11 히브리서 10:38에 인용되어 이신칭의의 핵심 근거가 되었다", "목회적활용":"구원은 행위가 아닌 믿음으로 말미암는다는 복음의 핵심을 붙잡아야 한다"}
