        {"영어원문":"His soul which is lifted up is not upright in him, but proud and crooked.", "한국어번역":"부풀어 오른 그의 영혼은 정직하지 않으며 교만하고 비뚤어져 있다.", "핵심통찰":"교만은 영혼을 비뚤어지게 만들며 하나님과의 관계를 왜곡시킨다"},
        {"영어원문":"Faith is the life of the just; they live by it, both in their trials and in their daily walk.", "한국어번역":"믿음은 의인의 생명이니 그들은 시련 속에서나 일상의 삶에서나 믿음으로 산다.", "핵심통찰":"믿음은 위기 때만이 아니라 일상의 매 순간을 살아가는 원리이다"}
