        {"원어":"מַסֵּכָה (마세카)", "의미_문법":"부어 만든 우상/주조상 - 명사. 금속을 녹여 만든 우상", "설교포인트":"아무리 귀한 재료로 만들어도 우상은 거짓이다"},
        {"원어":"מוֹרֶה (모레)", "의미_문법":"스승/가르치는 자 - 명사. 지도자와 교사", "설교포인트":"거짓 스승을 따르면 거짓된 길로 빠진다"},
        {"원어":"אִלֵּם (일렘)", "의미_문법":"벙어리의/말 못하는 - 형용사. 말할 수 없는 상태", "설교포인트":"말하지 못하는 우상은 기도에 응답할 수 없다"}
